r"""Test 6062 -- gen #37 route #413 (expected PASS): CONTROL: int `a / b` under `no_exception \all` with `b != 0` and `|a| <= 10**300` (the quotient is at most 10**300 < DBL_MAX), and `a / 3` with `|a| <= 10**308` (CPython ok, f(10**300, -1), g(10**308)). PROVED at base and candidate.
"""
# pycsl-expected: PASS
#@ requires b != 0
#@ requires - <= a and a <= 
#@ no_exception \all
def f(a: int, b: int) -> float:
    return a / b


#@ requires - <= a and a <= 
#@ no_exception \all
def g(a: int) -> float:
    return a / 3


if __name__ == "__main__":
    print(f(10**300, -1), g(10**308))
